Assume that $n=1$. For each compact interval $I\subset U$, there exists $C<+\infty$ such that for each $0<a\leq b$, each $\eta\in\{-1,+1\}$ and each $x,y\in I$
 \begin{equation}
 \left|\int_{\eta a}^{\eta b}e^{i\psi(x,y,|x-y|^{-1}\eta)}\sigma_P(x,y,|x-y|\partial_{x,y}\psi(x,y,|x-y|^{-1}\eta)\sigma_A(y,\xi)^{-(d+1)/m}d\eta\right|\leq Ca^{-1}\, .
 \end{equation}
